char s[] = "TRI_TUE_NHAN_TAO";
int x = 9;
for (int i = 8; i < 10; i++) {
    if (i % 2 == 0) x = x * 2;
    else x = x / 3;
}
cout << s[x];

def F(A, n):
    for i in range(1, n):
        x = A[i]
        j = i - 1
        while j >= 0 and A[j] > x:
            A[j + 1] = A[j]
            j = j - 1
        A[j + 1] = x
    return (A[n // 2] + A[n - 1]) / 2

float F(int A[], int n) {
    for (int i = 1; i < n; i++) {
        int x = A[i];
        int j = i - 1;
        while (j >= 0 && A[j] > x) {
            A[j + 1] = A[j];
            j = j - 1;
        }
        A[j + 1] = x;
    }
    return (A[n / 2] + A[n - 1]) / 2.0;
}

